// Isolation test (OS-12) — construct Bar with its declared inputs and nothing else, then exercise every
// public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { asProjection, height } from "../src/kernel/index.js";
import type { Candidate } from "../src/facts/index.js";
import { score, type Score } from "../src/observation/index.js";
import { AE5_OPEN, Bar, type PopulationSource, type SeparationRule } from "../src/calibration/index.js";

/** A partition handed in whole: Bar reads only the scores and the counts. */
const partition = (accepted: readonly number[], passedOver: readonly number[]): PopulationSource => {
  const members = (xs: readonly number[]) => xs.map((n) => ({ candidate: undefined as unknown as Candidate, score: score(n) as Score }));
  return {
    of: (level, component) =>
      asProjection("PopulationPartition", () => ({ level, component, accepted: members(accepted), passedOver: members(passedOver), excludedAccepted: 0, excludedPassedOver: 0 })),
  };
};
/** Separates whenever asked: the midpoint of the lowest accepted and the highest passed-over score. Test-only. */
const separating: SeparationRule = { separate: (a, p) => ({ kind: "separated", theta: (Math.min(...a) + Math.max(...p)) / 2 }) };
const parts = { populations: partition([0.9], [0.3]), separation: separating };
const at = height(1);

describe("Bar in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    for (const missing of Object.keys(parts)) expect(() => new Bar({ ...parts, [missing]: undefined } as never), missing).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    for (const slot of Object.keys(parts)) expect(() => new Bar({ ...parts, [slot]: {} } as never), slot).toThrow();
  });

  it("of answers differently when populations differs", () => {
    expect(new Bar(parts).of("easy", "q").compute(at)).not.toEqual(new Bar({ ...parts, populations: partition([], [0.3]) }).of("easy", "q").compute(at));
  });

  it("of answers differently when separation differs", () => {
    expect(new Bar(parts).of("easy", "q").compute(at)).not.toEqual(new Bar({ ...parts, separation: AE5_OPEN }).of("easy", "q").compute(at));
  });
});
